{
  "name": "泰克 DPO70000 系列示波器",
  "name_en": "Tektronix DPO70000 Series Oscilloscope",
  "manufacturer": "Tektronix",
  "description": "泰克 DPO70000 系列是一类多通道高带宽数字荧光示波器，适用于高速电子与射频信号的采集、触发、时基配置、波形读取和分析。根据类文档，其模拟带宽最高可达约 33 GHz。",
  "description_en": "The Tektronix DPO70000 series is a family of multi-channel high-bandwidth digital phosphor oscilloscopes used for high-speed electronic and RF signal acquisition, triggering, timebase configuration, waveform readout, and analysis. According to the class docstring, analog bandwidth reaches up to about 33 GHz.",
  "tag_hints": [
    "high-bandwidth oscilloscope",
    "waveform acquisition",
    "trigger control",
    "timebase configuration",
    "Tektronix DPO70000",
    "SCPI control",
    "high-speed signal analysis"
  ],
  "actions": [
    {
      "action_name": "auto-acquire_enhanced_enob",
      "description": "获取/设置增强 ENOB 采集选项。",
      "description_en": "Get/set the enhanced ENOB acquisition option."
    },
    {
      "action_name": "auto-acquire_enhanced_state",
      "description": "获取/设置增强采集状态。",
      "description_en": "Get/set the enhanced acquisition state."
    },
    {
      "action_name": "auto-acquire_interp_8bit",
      "description": "获取/设置 8 位插值模式。",
      "description_en": "Get/set the 8-bit interpolation mode."
    },
    {
      "action_name": "auto-acquire_magnivu",
      "description": "获取/设置 MagniVu 采集模式。",
      "description_en": "Get/set the MagniVu acquisition mode."
    },
    {
      "action_name": "auto-acquire_mode",
      "description": "获取/设置采集模式。",
      "description_en": "Get/set the acquisition mode."
    },
    {
      "action_name": "auto-acquire_num_avgs",
      "description": "获取/设置平均次数。",
      "description_en": "Get/set the number of averages."
    },
    {
      "action_name": "auto-acquire_num_envelop",
      "description": "获取/设置包络次数。",
      "description_en": "Get/set the number of envelopes."
    },
    {
      "action_name": "auto-acquire_num_samples",
      "description": "获取/设置采样点数。",
      "description_en": "Get/set the number of acquisition samples."
    },
    {
      "action_name": "auto-acquire_sampling_mode",
      "description": "获取/设置采样模式。",
      "description_en": "Get/set the sampling mode."
    },
    {
      "action_name": "auto-acquire_state",
      "description": "获取/设置采集状态。",
      "description_en": "Get/set the acquisition state."
    },
    {
      "action_name": "auto-acquire_stop_after",
      "description": "获取/设置采集停止条件。",
      "description_en": "Get/set the acquisition stop-after condition."
    },
    {
      "action_name": "auto-data_framestart",
      "description": "获取/设置波形帧起始位置。",
      "description_en": "Get/set the waveform frame start position."
    },
    {
      "action_name": "auto-data_framestop",
      "description": "获取/设置波形帧结束位置。",
      "description_en": "Get/set the waveform frame stop position."
    },
    {
      "action_name": "auto-data_source",
      "description": "获取/设置波形数据源。",
      "description_en": "Get/set the waveform data source."
    },
    {
      "action_name": "auto-data_start",
      "description": "获取/设置波形数据起始点。",
      "description_en": "Get/set the waveform data start point."
    },
    {
      "action_name": "auto-data_stop",
      "description": "获取/设置波形数据结束点。",
      "description_en": "Get/set the waveform data stop point."
    },
    {
      "action_name": "auto-data_sync_sources",
      "description": "获取/设置数据源同步选项。",
      "description_en": "Get/set the data source synchronization option."
    },
    {
      "action_name": "auto-force_trigger",
      "description": "强制产生一次触发事件。",
      "description_en": "Force a trigger event."
    },
    {
      "action_name": "auto-horiz_delay_mode",
      "description": "获取/设置水平延迟模式。",
      "description_en": "Get/set the horizontal delay mode."
    },
    {
      "action_name": "auto-horiz_delay_pos",
      "description": "获取/设置水平延迟位置。",
      "description_en": "Get/set the horizontal delay position."
    },
    {
      "action_name": "auto-horiz_delay_time",
      "description": "获取/设置水平延迟时间。",
      "description_en": "Get/set the horizontal delay time."
    },
    {
      "action_name": "auto-horiz_main_pos",
      "description": "获取/设置主时基水平位置。",
      "description_en": "Get/set the main horizontal position."
    },
    {
      "action_name": "auto-horiz_mode",
      "description": "获取/设置水平时基模式。",
      "description_en": "Get/set the horizontal timebase mode."
    },
    {
      "action_name": "auto-horiz_pos",
      "description": "获取/设置水平位置。",
      "description_en": "Get/set the horizontal position."
    },
    {
      "action_name": "auto-horiz_record_length",
      "description": "获取/设置记录长度。",
      "description_en": "Get/set the record length."
    },
    {
      "action_name": "auto-horiz_record_length_lim",
      "description": "获取/设置记录长度限制。",
      "description_en": "Get/set the record length limit."
    },
    {
      "action_name": "auto-horiz_roll",
      "description": "获取/设置滚动模式。",
      "description_en": "Get/set the roll mode."
    },
    {
      "action_name": "auto-horiz_sample_rate",
      "description": "获取/设置采样率。",
      "description_en": "Get/set the sample rate."
    },
    {
      "action_name": "auto-horiz_scale",
      "description": "获取/设置水平刻度。",
      "description_en": "Get/set the horizontal scale."
    },
    {
      "action_name": "auto-horiz_unit",
      "description": "获取/设置水平单位。",
      "description_en": "Get/set the horizontal unit."
    },
    {
      "action_name": "auto-outgoing_binary_format",
      "description": "获取/设置输出二进制格式。",
      "description_en": "Get/set the outgoing binary format."
    },
    {
      "action_name": "auto-outgoing_byte_order",
      "description": "获取/设置输出字节序。",
      "description_en": "Get/set the outgoing byte order."
    },
    {
      "action_name": "auto-outgoing_n_bytes",
      "description": "获取/设置每个输出数据点的字节数。",
      "description_en": "Get/set the number of bytes per outgoing data point."
    },
    {
      "action_name": "auto-outgoing_waveform_encoding",
      "description": "获取/设置输出波形编码。",
      "description_en": "Get/set the outgoing waveform encoding."
    },
    {
      "action_name": "auto-run",
      "description": "启动示波器采集并使能触发。",
      "description_en": "Start oscilloscope acquisition and enable triggering."
    },
    {
      "action_name": "auto-select_fastest_encoding",
      "description": "选择与当前数据源兼容的最快波形传输编码。",
      "description_en": "Select the fastest waveform transfer encoding compatible with the current data source."
    },
    {
      "action_name": "auto-stop",
      "description": "停止示波器采集并禁用触发。",
      "description_en": "Stop oscilloscope acquisition and disable triggering."
    },
    {
      "action_name": "auto-trigger_state",
      "description": "获取触发状态。",
      "description_en": "Get the trigger state."
    },
    {
      "action_name": "auto-channel",
      "description": "获取通道对象。",
      "description_en": "Get the channel objects."
    },
    {
      "action_name": "auto-math",
      "description": "获取数学波形对象。",
      "description_en": "Get the math waveform objects."
    },
    {
      "action_name": "auto-ref",
      "description": "获取参考波形对象。",
      "description_en": "Get the reference waveform objects."
    },
    {
      "action_name": "auto-name",
      "description": "获取/设置仪器名称。",
      "description_en": "Get/set the instrument name."
    },
    {
      "action_name": "auto-read_waveform",
      "description": "从当前数据源读取波形数据。",
      "description_en": "Read waveform data from the current data source."
    },
    {
      "action_name": "auto-sendcmd",
      "description": "向示波器发送原始 SCPI 命令。",
      "description_en": "Send a raw SCPI command to the oscilloscope."
    },
    {
      "action_name": "auto-query",
      "description": "向示波器发送原始 SCPI 查询并返回响应。",
      "description_en": "Send a raw SCPI query to the oscilloscope and return the response."
    }
  ]
}

